foreach($order as$key){$attribute=$product->get_attributes()[$key]??null;if(!$attribute||!$attribute->get_variation())continue;$values=[];if($attribute->is_taxonomy()){foreach(wc_get_product_terms($product_id,$key,['fields'=>'all'])as$term)$values[]=['value'=>$term->slug,'label'=>$term->name];}else{foreach($attribute->get_options()as$value)$values[]=['value'=>$value,'label'=>$value];}usort($values,function($a,$b){return strnatcasecmp($a['label'],$b['label']);});$groups[]=['key'=>'attribute_'.$key,'label'=>$labels[$key]??wc_attribute_label($key),'values'=>$values];}
$min_price=$product->is_type('variable')?$product->get_variation_price('min',true):wc_get_price_to_display($product);$max_price=$product->is_type('variable')?$product->get_variation_price('max',true):$min_price;
